package com.mushafi.app;
import android.app.*;import android.content.*;import android.os.*;import android.service.notification.StatusBarNotification;import org.json.*;import java.util.*;
/** Native alarm/notification behavior, with real AlarmManager and NotificationManager. */
public final class NotificationChecks {
 static void need(boolean value,String message)throws Exception{if(!value)throw new Exception(message);}
 static Notification notice(Context c,int id){for(StatusBarNotification n:((NotificationManager)c.getSystemService(Context.NOTIFICATION_SERVICE)).getActiveNotifications())if(n.getId()==id)return n.getNotification();return null;}
 static long post(Context c,int id){for(StatusBarNotification n:((NotificationManager)c.getSystemService(Context.NOTIFICATION_SERVICE)).getActiveNotifications())if(n.getId()==id)return n.getPostTime();return 0;}
 static PrayerScheduler.Event near(PrayerSettings s,long now)throws Exception{PrayerScheduler.Event nearest=null;for(PrayerScheduler.Event e:PrayerScheduler.events(s,now))if(e.key.equals("dhuhr")&&e.kind.equals("adhan")&&(nearest==null||Math.abs(e.at-now)<Math.abs(nearest.at-now)))nearest=e;return nearest;}
 public static void run(Instrumentation test)throws Exception{Context c=test.getTargetContext();NotificationManager nm=(NotificationManager)c.getSystemService(Context.NOTIFICATION_SERVICE);String originalPrayer=c.getSharedPreferences("prayer_times",0).getString("settings",null),originalPlan=KhatmaScheduler.prefs(c).getString("plan",null);boolean originalAlarm=AdhanPlaybackService.enabled(c);TimeZone zone=TimeZone.getDefault();try{
  c.getSharedPreferences("prayer_audio",0).edit().putBoolean("onSilent",false).commit();PrayerSettings s=new PrayerSettings(new JSONObject().put("enabled",true).put("confirmed",true).put("timezone","UTC").put("latitude",20).put("longitude",0).put("voice","silent"));PrayerScheduler.channels(c,s);
  Set<String> ids=new HashSet<>();long last=Long.MIN_VALUE;for(PrayerScheduler.Event event:PrayerScheduler.events(s,System.currentTimeMillis())){need(event.at>=last,"chronological alarms");need(ids.add(event.id),"unique event IDs");last=event.at;}
  Notification fallback=PrayerScheduler.notification(c,s,"dhuhr","adhan",System.currentTimeMillis(),false,false,false);Notification foreground=PrayerScheduler.notification(c,s,"dhuhr","adhan",System.currentTimeMillis(),false,false,true);Notification stopped=PrayerScheduler.notification(c,s,"dhuhr","adhan",System.currentTimeMillis(),false,false,false,true);need(fallback.getGroup()==null,"system fallback retains channel alert");need(foreground.getGroup()!=null&&foreground.getGroupAlertBehavior()==Notification.GROUP_ALERT_SUMMARY,"service suppresses duplicate channel audio");need(stopped.getGroup()!=null,"finished controlled playback never replays channel sound");need(fallback.getLargeIcon()==null,"no duplicate large icon");
  c.getSharedPreferences("prayer_audio",0).edit().putBoolean("onSilent",true).commit();PrayerSettings voiced=new PrayerSettings(new JSONObject(s.json.toString()).put("voice","afasy"));Context blocked=new ContextWrapper(c){@Override public ComponentName startForegroundService(Intent intent){throw new IllegalStateException("QA background start restricted");}};PrayerScheduler.notifyEvent(blocked,voiced,"dhuhr","adhan",System.currentTimeMillis(),true);Thread.sleep(300);Notification recovered=notice(c,7099);need(recovered!=null&&recovered.getGroup()==null&&recovered.getChannelId().equals("prayer_adhan_afasy_v1"),"blocked service falls back to an unsuppressed regular alert");need(c.getSharedPreferences("prayer_audio",0).getString("error","").contains("إشعار النظام"),"fallback error reported truthfully");c.getSharedPreferences("prayer_audio",0).edit().putBoolean("onSilent",false).commit();
  for(String key:PrayerSettings.KEYS){s.row(key).put("adhan",false).put("reminder",false).put("atIqama",false);}s.row("dhuhr").put("adhan",true);long target=System.currentTimeMillis()-60000;for(int j=0;j<4;j++){PrayerScheduler.Event e=near(s,target);double longitude=s.json.optDouble("longitude")+(e.at-target)/240000.0;while(longitude>180)longitude-=360;while(longitude< -180)longitude+=360;s.json.put("longitude",longitude);}s.save(c);PrayerScheduler.Event event=near(s,target);long now=System.currentTimeMillis();need(event.at<=now&&now-event.at<=120000,"test current prayer occurrence");Intent alarm=new Intent(PrayerScheduler.ACTION).putExtra("at",event.at).putExtra("id",event.id).putExtra("kind",event.kind).putExtra("key",event.key);PrayerScheduler.deliver(c,alarm);Thread.sleep(300);int prayerId=Math.abs((event.key+event.kind).hashCode());long first=post(c,prayerId);need(first>0,"current prayer posted");PrayerScheduler.deliver(c,alarm);Thread.sleep(200);need(post(c,prayerId)==first,"repeated receiver never reposts same prayer");PrayerScheduler.deliver(c,new Intent(alarm).putExtra("at",now-180000));need(post(c,prayerId)==first,"stale alarm rejected");
  s.json.put("reminderMinutes",1);s.row("dhuhr").put("iqama",2).put("reminder",true).put("atIqama",true);long expiredTarget=(System.currentTimeMillis()/60000)*60000-120000;for(int j=0;j<4;j++){PrayerScheduler.Event e=near(s,expiredTarget);double longitude=s.json.optDouble("longitude")+(e.at-expiredTarget)/240000.0;while(longitude>180)longitude-=360;while(longitude< -180)longitude+=360;s.json.put("longitude",longitude);}s.save(c);PrayerScheduler.Event expired=null;for(PrayerScheduler.Event e:PrayerScheduler.events(s,System.currentTimeMillis()))if(e.key.equals("dhuhr")&&e.kind.equals("reminder")&&e.at+60000<=System.currentTimeMillis()&&System.currentTimeMillis()-e.at<120000)expired=e;need(expired!=null,"test late reminder within receiver tolerance but beyond iqama");int reminderId=Math.abs("dhuhrreminder".hashCode());nm.cancel(reminderId);PrayerScheduler.deliver(c,new Intent(PrayerScheduler.ACTION).putExtra("at",expired.at).putExtra("id",expired.id).putExtra("kind","reminder").putExtra("key","dhuhr"));Thread.sleep(200);need(notice(c,reminderId)==null,"expired pre-iqama reminder never posted");
  long milliseconds=System.currentTimeMillis()%86400000L;int offset=(int)(9*3600000L+30000-milliseconds);while(offset>12*3600000)offset-=86400000;while(offset< -12*3600000)offset+=86400000;TimeZone.setDefault(new SimpleTimeZone(offset,"QA-Daily"));JSONObject plan=new JSONObject().put("version",1).put("id","notifications-qa").put("startDay","2026-01-01").put("days",30).put("dailyPages",JSONObject.NULL).put("reminder","daily").put("position",17).put("wardIndex",0).put("read",new JSONObject());KhatmaScheduler.save(c,plan.toString());KhatmaScheduler.Event due=KhatmaScheduler.events(plan,s,System.currentTimeMillis()).get(0);need(due.at<=System.currentTimeMillis()&&System.currentTimeMillis()-due.at<120000,"test due daily reminder");KhatmaScheduler.prefs(c).edit().putLong("next",due.at).putString("nextId",due.id).commit();KhatmaScheduler.schedule(c);Thread.sleep(300);long firstKhatma=post(c,KhatmaScheduler.NOTICE);need(firstKhatma>0,"due reminder recovered during reschedule");need(KhatmaScheduler.prefs(c).getStringSet("sent",Collections.emptySet()).contains(due.id),"recovery recorded");KhatmaScheduler.deliver(c,new Intent(KhatmaScheduler.ACTION).putExtra("at",due.at).putExtra("id",due.id));Thread.sleep(200);need(post(c,KhatmaScheduler.NOTICE)==firstKhatma,"khatma reminder delivered once");need(KhatmaScheduler.prefs(c).getLong("next",0)>System.currentTimeMillis(),"next day reminder queued");
  String extra="qa_unrelated_notification";NotificationChannel channel=new NotificationChannel(extra,"QA",NotificationManager.IMPORTANCE_LOW);channel.setSound(null,null);nm.createNotificationChannel(channel);nm.notify(90021,new Notification.Builder(c,extra).setSmallIcon(AppIdentity.notificationIcon(c)).setContentTitle("Unrelated audio notification").build());Thread.sleep(200);s.json.put("enabled",false);s.save(c);PrayerScheduler.schedule(c);Thread.sleep(300);need(notice(c,prayerId)==null,"disabled prayers clear only prayer alerts");need(notice(c,KhatmaScheduler.NOTICE)!=null,"disabling prayers preserves khatma alert");need(notice(c,90021)!=null,"disabling prayers preserves unrelated notification");need(KhatmaScheduler.prefs(c).getLong("next",0)>System.currentTimeMillis(),"independent khatma schedule preserved");
 }finally{TimeZone.setDefault(zone);nm.cancel(90021);PrayerScheduler.cancelPrayerNotifications(c);if(originalPrayer==null)c.getSharedPreferences("prayer_times",0).edit().remove("settings").commit();else c.getSharedPreferences("prayer_times",0).edit().putString("settings",originalPrayer).commit();if(originalPlan==null)KhatmaScheduler.clear(c);else KhatmaScheduler.save(c,originalPlan);c.getSharedPreferences("prayer_audio",0).edit().putBoolean("onSilent",originalAlarm).commit();PrayerScheduler.schedule(c);}}
}
